const labels={U1:'U1 · FPGA',J5:'J5 · ASIC connector',J6:'J6 · ASIC connector',J4:'J4 · Custom cable',NC:'Six saved NC pins to review'};
const natural=(a,b)=>a.localeCompare(b,undefined,{numeric:true});
for(const c of [...data.components].sort((a,b)=>natural(a.reference,b.reference))){const o=document.createElement('option');o.value=c.reference;o.textContent=c.reference+' · '+c.value;$('#component').append(o)}
$('#hash').textContent=data.source.boardSha256;
function detail(id){const p=byId.get(id);if(!p)return;selected=id;
 $('#detail').innerHTML=`<p class="eyebrow">Selected pin</p><h2>${esc(p.id)}</h2><span class="badge ${p.visualStatusCode}">${esc(p.statusLabel)}</span><dl><dt>Pin function</dt><dd>${esc(p.function||'Passive terminal')}</dd><dt>Current net</dt><dd>${esc(p.net||'None assigned')}</dd>${p.bank?`<dt>FPGA bank / supply</dt><dd>${esc(p.bank)} · ${esc(p.bankVoltage||'See rail design')}</dd>`:''}<dt>Physical location</dt><dd>${p.physicalPads.map(a=>`${a.x_mm.toFixed(3)}, ${a.y_mm.toFixed(3)} mm`).join('<br>')}</dd></dl><p class="detail-note">${esc(p.note)}${p.reviewSource?` <a href="${esc(p.reviewSource)}" target="_blank" rel="noopener">Manufacturer source</a>`:''}</p>${p.proposal?`<div class="proposal"><strong>Draft contact proposal only</strong><span>${esc(p.proposal.signal)}</span><p>FPGA ball: ${esc(p.proposal.fpgaBall)}. This is not a current net assignment.</p></div>`:''}<p class="keyboard">Click a pin to explain it. Use arrow keys to move between pads; Enter selects. Scroll the map or use + to enlarge labels.</p>`;
 document.querySelectorAll('[data-pin-id]').forEach(g=>{const on=g.dataset.pinId===id;g.classList.toggle('selected',on);g.setAttribute('aria-pressed',String(on));g.setAttribute('tabindex',on?'0':'-1')});
 if(ref==='NC')document.querySelectorAll('.nc-list button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===id)));
 const url=new URL(location.href);url.searchParams.set('component',ref);url.searchParams.delete('ref');url.searchParams.set('pin',id);history.replaceState(null,'',url);
}
function map(){
 $('#map-heading').textContent=labels[ref]||ref+' · '+byRef.get(ref).value;$('#map-tools').hidden=ref==='NC';
 document.querySelectorAll('[data-ref]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.ref===ref)));
 $('#component').value=byRef.has(ref)?ref:'';
 if(ref==='NC'){$('#map-meta').textContent='2 require ground; 4 unused FB2 connections need grounding review. CAD is unchanged.';$('#map').innerHTML='<div class="nc-list">'+data.pins.filter(p=>p.statusCode==='nc').map(p=>`<button data-id="${p.id}" aria-pressed="false"><strong>${p.id}</strong><span>${esc(p.function)}</span><em>${p.mark} ${p.validationStatus==='ground_required'?'GND required':'Review'}</em></button>`).join('')+'</div>';document.querySelectorAll('.nc-list button').forEach(b=>b.onclick=()=>detail(b.dataset.id));detail(byId.get(selected)?.statusCode==='nc'?selected:'U1.L9');return}
 const c=byRef.get(ref),ps=c.pins.map(id=>byId.get(id)),[x0,y0,x1,y1]=c.bounds_mm;
 let scale=ref==='U1'?50:['J5','J6'].includes(ref)?75:105,margin=45,radius=ref==='U1'?16:['J5','J6'].includes(ref)?14:13;
 let width=(x1-x0)*scale+margin*2,height=(y1-y0)*scale+margin*2;
 const numU=ps.filter(p=>p.statusCode==='unassigned').length,numNC=ps.filter(p=>p.statusCode==='nc').length;
 $('#map-meta').textContent=`${ps.length} electrical pins · ${numU} unassigned · ${numNC} NC in saved CAD${c.side==='Back'?' · back side, seen through board':''}`;
 let svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" role="group" aria-label="${esc(ref)} physical pad map"><text x="12" y="18" class="geom-title">Native pad centers · PCB up ↑</text>`;
 for(const p of ps){const [fill,stroke,text]=colors[p.visualStatusCode];for(const [i,a]of p.physicalPads.entries()){
 const x=(a.x_mm-x0)*scale+margin,y=(a.y_mm-y0)*scale+margin;let aria=`${p.id}, ${p.statusLabel}, ${p.function||p.net||'no assigned signal'}`;
 svg+=`<g data-pin-id="${p.id}" data-status="${p.statusCode}" data-x="${x}" data-y="${y}" role="button" aria-label="${esc(aria)}" tabindex="-1"><title>${esc(aria)}</title><circle cx="${x}" cy="${y}" r="${radius}" fill="${fill}" stroke="${stroke}" stroke-width="1.1"/><text x="${x}" y="${y-1}" text-anchor="middle" dominant-baseline="central" font-size="${ref==='U1'?10:11}" font-weight="600" fill="${text}">${esc(p.pin)}</text><text x="${x}" y="${y+10}" text-anchor="middle" font-size="8" fill="${text}">${esc(p.mark)}</text></g>`}}
 svg+='</svg>';$('#map').innerHTML=svg;
 const svgEl=$('#map svg');svgEl.style.width=width*zoom+'px';svgEl.style.minWidth=ref==='U1'?'600px':'0';
 document.querySelectorAll('[data-pin-id]').forEach(g=>{g.onclick=()=>detail(g.dataset.pinId);g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();detail(g.dataset.pinId)}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();const gs=[...document.querySelectorAll('[data-pin-id]')];let target;if(e.key==='Home')target=gs[0];else if(e.key==='End')target=gs.at(-1);else{const x=+g.dataset.x,y=+g.dataset.y,axis=e.key==='ArrowLeft'||e.key==='ArrowRight'?'x':'y',sign=e.key==='ArrowLeft'||e.key==='ArrowUp'?-1:1;target=gs.filter(a=>(+a.dataset[axis]-(axis==='x'?x:y))*sign>0.01).sort((a,b)=>{const score=t=>{let dx=Math.abs(+t.dataset.x-x),dy=Math.abs(+t.dataset.y-y);return axis==='x'?dx+dy*25:dy+dx*25};return score(a)-score(b)})[0]}if(target){detail(target.dataset.pinId);target.focus();target.scrollIntoView({block:'nearest',inline:'nearest'})}}}});
 if(!ps.some(p=>p.id===selected))selected=ps.find(p=>p.statusCode==='unassigned')?.id||ps[0].id;detail(selected);applyFilter();
}
function applyFilter(){const f=$('#filter').value;document.querySelectorAll('[data-pin-id]').forEach(g=>g.classList.toggle('dim',f!=='all'&&(f==='assigned'?!g.dataset.status.startsWith('assigned'):g.dataset.status!==f)))}
function switchRef(r,id){ref=r;if(id)selected=id;zoom=1;map();$('#search-results').hidden=true}
document.querySelectorAll('[data-ref]').forEach(b=>b.onclick=()=>switchRef(b.dataset.ref));$('#component').onchange=e=>{if(e.target.value)switchRef(e.target.value)};$('#filter').onchange=applyFilter;
$('#zoom-in').onclick=()=>{zoom=Math.min(2.5,zoom+.25);map()};$('#zoom-out').onclick=()=>{zoom=Math.max(.65,zoom-.25);map()};$('#fit').onclick=()=>{if(ref==='NC')return;const c=byRef.get(ref),scale=ref==='U1'?50:['J5','J6'].includes(ref)?75:105;zoom=Math.max(.65,Math.min(1,($('#map').clientWidth-22)/((c.bounds_mm[2]-c.bounds_mm[0])*scale+90)));map()};
$('#search').oninput=e=>{const q=e.target.value.trim().toLowerCase(),out=$('#search-results');if(!q){out.hidden=true;return}const found=data.pins.filter(p=>[p.id,p.function,p.net,p.proposal?.signal].filter(Boolean).some(v=>v.toLowerCase().includes(q)));out.hidden=false;out.innerHTML=`<p>${found.length} matching pins${found.length>40?' · showing first 40':''}</p>`+found.slice(0,40).map(p=>`<button data-found="${p.id}"><strong>${p.id}</strong> ${esc(p.function||p.net||p.statusLabel)}</button>`).join('');out.querySelectorAll('button').forEach(b=>b.onclick=()=>{const p=byId.get(b.dataset.found);switchRef(p.reference,p.id);$('#search').value='';const el=[...document.querySelectorAll('[data-pin-id]')].find(g=>g.dataset.pinId===p.id);el?.scrollIntoView({block:'nearest',inline:'nearest'})})};
$('#search').onkeydown=e=>{if(e.key==='Escape')$('#search-results').hidden=true;if(e.key==='ArrowDown'){e.preventDefault();$('#search-results button')?.focus()}};
document.addEventListener('click',e=>{if(!e.target.closest('.search'))$('#search-results').hidden=true});
const query=new URLSearchParams(location.search), requested=query.get('component')||query.get('ref');if(requested==='NC'||byRef.has(requested))ref=requested;if(byId.has(query.get('pin')))selected=query.get('pin');if(query.get('embed')==='1')document.body.classList.add('embed');map();
window.PinMap={data,select:(id)=>{const p=byId.get(id);if(p)switchRef(p.reference,id)}};
if(query.get('embed')==='1'&&parent!==window)new ResizeObserver(()=>parent.postMessage({type:'fpga-pin-map-height',height:document.documentElement.scrollHeight},location.origin)).observe(document.body);
